import React, { useEffect, useState } from 'react';

function App() {
  const [data, setData] = useState({
    defender: 'A Measly Worm',
    winner: 'None yet',
    numberOfTimes: 0,
    victoryReason: 'It is a measly worm',
    emoji: '🐛',
    color: 'green',
  });

  useEffect(() => {

    console.log('Data updated:', data);
  }, [data]);

  const [input, setInput] = useState('');

  const handleSend = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input + ' | ' + data.defender }),
      });
      const result = await response.json();
      console.log('Fetched data:', result);
      setData(result.result);
      console.log('Data set:', data);
      setInput('');
    } catch (err) {
      console.error('Error sending message:', err);
    }
  };

  return (
    <div className="container">
      <h1 style={{ color: data.color }}>{data.defender}</h1>
      <h2>Winner: {data.winner}</h2>
      <h3>Number of Times: {data.numberOfTimes}</h3>
      <h4>Victory Reason: {data.victoryReason}</h4>
      <h5>{data.emoji}</h5>
      <input
        type="text"
        value={input}
        onChange={e => setInput(e.target.value)}
        placeholder="Type your challenger's name"
      />
      <button onClick={handleSend}>Battle!</button>
    </div>
  );
}

export default App;
